// ---------------------------------------------------------------------------
// SPLIT COHORT INTO PATIENT ITEMS
// Input: the parsed n8n_cohort.json produced by build_cohort.py, which is the
// join of Zafar's uncertainty output and Denis's SHAP output.
// Output: one n8n item per patient record, stamped with an orchestration run id.
// ---------------------------------------------------------------------------

// n8n's Extract From File node nests parsed JSON under a `data` key by
// default. Unwrap it if present, otherwise use the object as-is, so this
// works regardless of the extract node's Destination Key setting.
const raw  = $input.first().json;
const file = (raw && raw.data && raw.data.records) ? raw.data : raw;

const meta = file.cohort_metadata || {};
const records = file.records || [];

if (!records.length) {
  throw new Error('No records in cohort file. Check the Read node path points at n8n_cohort.json and that build_cohort.py has been run.');
}

const runId = 'ORC-' + new Date().toISOString().replace(/[-:.TZ]/g, '').slice(0, 14);

return records.map((r, i) => ({
  json: {
    ...r,
    run_id: runId,
    case_index: i + 1,
    cohort_size: records.length,
    dispatched_at: new Date().toISOString(),
    // cohort-level context carried onto every patient for the audit trail
    fl_checkpoint: meta.fl_checkpoint || r.fl_checkpoint || 'unknown',
    fl_round: meta.fl_round ?? r.fl_round ?? null,
    cohort_ece: meta.calibration?.expected_calibration_error ?? r.cohort_ece ?? null,
    cohort_confidence_gap: meta.calibration?.confidence_gap ?? r.cohort_confidence_gap ?? null,
    blind_classes: Object.entries(meta.class_reliability || {})
      .filter(([, v]) => v.model_blind).map(([k]) => k)
  }
}));

// ---------------------------------------------------------------------------
// NORMALISE AGENT RESPONSE + GOVERNANCE SCORING  (integrated edition)
//
// Governance now runs on the FEDERATED PIPELINE'S OWN measured signals rather
// than on guessed thresholds:
//
//   normalized_entropy / uncertainty_level  <- Zafar, Monte Carlo Dropout
//   qrs|p_wave|t_wave_shap_signed           <- Denis, SHAP by ECG region
//   class_recall / class_roc_auc            <- per-class evaluation
//   cohort_confidence_gap (ECE)             <- calibration analysis
//
// Threshold justification (outputs/uncertainty/uncertainty_metrics.json):
//   accuracy at Low uncertainty     = 96.8%
//   accuracy at High uncertainty    = 66.4%
// A 30-point accuracy collapse is the empirical basis for escalating High.
// ---------------------------------------------------------------------------

const URGENCY_WEIGHT = { Low: 0.0, Medium: 0.5, High: 0.85, Critical: 1.0 };

// Weights sum to 1.0 -> risk_score bounded [0, 1]
const W = { abnormal: 0.30, entropy: 0.30, urgency: 0.25, unreliable_class: 0.15 };

const RISK_ESCALATION   = 0.45;   // composite threshold
const RECALL_FLOOR      = 0.50;   // predicted class must be detectable at least this well
const CALIBRATED_FLOOR  = 0.70;   // confidence floor AFTER correcting for ECE


// ---------------------------------------------------------------------------
// SOURCE RESOLVER
// $('Node').item does NOT advance inside a manual loop over $input.all() - it
// stays pinned to a single item, which silently gives every patient the same
// clinical fields. Resolve per-item instead: prefer the patient_id echoed back
// by the API, fall back to n8n's paired-item lineage, then to position.
// ---------------------------------------------------------------------------
const SRC   = $('Split Cohort Into Patients').all().map(x => x.json);
const BY_ID = new Map(SRC.filter(s => s && s.patient_id).map(s => [s.patient_id, s]));

function resolveSrc(item, i) {
  const j = item.json || {};
  const pid = j.patient_id || (j.features && j.features.patient_id) || null;
  if (pid && BY_ID.has(pid)) return BY_ID.get(pid);
  try {
    const m = $('Split Cohort Into Patients').itemMatching(i);
    if (m && m.json) return m.json;
  } catch (e) { /* pairing unavailable */ }
  return SRC[i] || {};
}

const out = [];

const _items = $input.all();
for (let _i = 0; _i < _items.length; _i++) {
  const item = _items[_i];
  const api = item.json;
  const src = resolveSrc(item, _i);

  const agent = api.agent_output || {};
  const feats = api.features || {};

  const prediction  = feats.prediction || src.prediction;
  const rawConf     = Number(feats.confidence ?? src.confidence ?? 0);
  const urgency     = agent.urgency_level || 'Unknown';
  const parseOk     = api.status === 'success';

  // The model is measurably over-confident (negative confidence gap), so the
  // raw softmax value is corrected before it is compared against the floor.
  const gap             = Number(src.cohort_confidence_gap ?? 0);
  const calibratedConf  = Math.max(0, Math.min(1, rawConf + gap));

  const normEntropy     = Number(src.normalized_entropy ?? 0);
  const uncertainty     = src.uncertainty_level || 'Unknown';
  const classRecall     = src.class_recall == null ? null : Number(src.class_recall);
  const blindClasses    = src.blind_classes || [];

  // API returns clinical_status directly (v2); fall back to deriving it.
  const clinicalStatus = api.clinical_status
    || (prediction !== 'Normal Sinus Rhythm' ? 'Abnormal' : 'Normal');
  const isAbnormal = clinicalStatus === 'Abnormal';

  const classUnreliability = (classRecall == null) ? 0.5 : (1 - classRecall);

  // ---- composite risk score -------------------------------------------------
  const riskScore = Number((
      W.abnormal          * (isAbnormal ? 1 : 0)
    + W.entropy           * normEntropy
    + W.urgency           * (URGENCY_WEIGHT[urgency] ?? 0.5)
    + W.unreliable_class  * classUnreliability
  ).toFixed(4));

  // ---- escalation gates -----------------------------------------------------
  const reasons = [];

  if (uncertainty === 'High')
    reasons.push('MC-Dropout uncertainty High (accuracy in this band is 66.4% vs 96.8% at Low)');

  if (isAbnormal)
    reasons.push('Abnormal rhythm predicted (' + prediction + ')');

  if (calibratedConf < CALIBRATED_FLOOR)
    reasons.push('Calibration-corrected confidence ' + (calibratedConf * 100).toFixed(1) + '% below ' + (CALIBRATED_FLOOR * 100) + '% floor');

  if (urgency === 'High' || urgency === 'Critical')
    reasons.push('Agent assigned ' + urgency + ' urgency');

  if (classRecall != null && classRecall < RECALL_FLOOR)
    reasons.push('Predicted class ' + (src.predicted_class_aami || '?') + ' has recall ' + classRecall.toFixed(3) + ' - model unreliable on this class');

  if (riskScore >= RISK_ESCALATION)
    reasons.push('Composite risk score ' + riskScore + ' >= ' + RISK_ESCALATION);

  if (!parseOk)
    reasons.push('Agent returned status "' + api.status + '" - output not structurally verified');

  // ---- blind-class exposure -------------------------------------------------
  // The federated model has zero recall on some classes, so it can NEVER emit
  // them. A high-uncertainty prediction of a class it CAN emit is therefore the
  // observable signature of a masked minority beat. This cannot be detected by
  // checking the predicted class alone.
  const blindRisk = blindClasses.length > 0
                 && uncertainty !== 'Low'
                 && !blindClasses.includes(src.predicted_class_aami);
  if (blindRisk)
    reasons.push('BLIND-CLASS EXPOSURE: model cannot detect class(es) ' + blindClasses.join('/') + '; uncertain prediction may mask one');

  // ---- disagreement detector -------------------------------------------------
  const disagreement = (urgency === 'Low')
                    && (uncertainty === 'High' || calibratedConf < CALIBRATED_FLOOR);
  if (disagreement)
    reasons.push('DISAGREEMENT: agent urgency Low but pipeline uncertainty high');

  // ---- ground-truth check (research evaluation only, NOT a clinical gate) ----
  const groundTruthMiss = src.correct === false;

  out.push({
    json: {
      // -- provenance --
      run_id: src.run_id,
      patient_id: api.patient_id || src.patient_id,
      case_index: src.case_index,
      sample_index: src.sample_index,
      fl_checkpoint: src.fl_checkpoint,
      fl_round: src.fl_round,
      dispatched_at: src.dispatched_at,
      analysed_at: new Date().toISOString(),

      // -- federated model evidence --
      prediction: prediction,
      predicted_class_aami: src.predicted_class_aami,
      true_class_aami: src.true_class_aami,
      correct: src.correct,
      confidence: rawConf,
      calibrated_confidence: Number(calibratedConf.toFixed(4)),
      uncertainty_level: uncertainty,
      normalized_entropy: normEntropy,
      predictive_entropy: src.predictive_entropy,
      mutual_information: src.mutual_information,
      class_recall: classRecall,
      class_roc_auc: src.class_roc_auc,

      // -- SHAP evidence --
      dominant_ecg_region: src.dominant_ecg_region,
      qrs_shap_signed: src.qrs_shap_signed,
      p_wave_shap_signed: src.p_wave_shap_signed,
      t_wave_shap_signed: src.t_wave_shap_signed,
      ehr_triage_note: src.ehr_triage_note,

      // -- flattened agent output --
      api_status: api.status,
      urgency_level: urgency,
      suggested_next_action: agent.suggested_next_action || 'Not provided',
      doctor_technical_alert: agent.doctor_technical_alert || 'Not provided',
      family_reassurance_message: agent.family_reassurance_message || 'Not provided',
      pipeline_recommendation: src.pipeline_recommendation || 'Not provided',

      // -- governance decision --
      clinical_status: clinicalStatus,
      risk_score: riskScore,
      low_confidence_flag: calibratedConf < CALIBRATED_FLOOR,
      disagreement_flag: disagreement,
      blind_class_risk: blindRisk,
      ground_truth_miss: groundTruthMiss,
      human_review_required: reasons.length > 0,
      review_reason: reasons.length ? reasons.join(' | ') : 'All governance gates passed',
      governance_policy: 'v2.0-integrated weights{abn .30, ent .30, urg .25, cls .15} esc' + RISK_ESCALATION + ' recall_floor' + RECALL_FLOOR + ' conf_floor' + CALIBRATED_FLOOR + ' (ECE-corrected)'
    }
  });
}

return out;

// ---------------------------------------------------------------------------
// FAIL-SAFE BRANCH
// Reached when the FastAPI call errors, times out, or Ollama is unreachable.
// An unreachable agent is treated as maximum uncertainty and escalated.
// A patient is never silently dropped.
// ---------------------------------------------------------------------------


// ---------------------------------------------------------------------------
// SOURCE RESOLVER
// $('Node').item does NOT advance inside a manual loop over $input.all() - it
// stays pinned to a single item, which silently gives every patient the same
// clinical fields. Resolve per-item instead: prefer the patient_id echoed back
// by the API, fall back to n8n's paired-item lineage, then to position.
// ---------------------------------------------------------------------------
const SRC   = $('Split Cohort Into Patients').all().map(x => x.json);
const BY_ID = new Map(SRC.filter(s => s && s.patient_id).map(s => [s.patient_id, s]));

function resolveSrc(item, i) {
  const j = item.json || {};
  const pid = j.patient_id || (j.features && j.features.patient_id) || null;
  if (pid && BY_ID.has(pid)) return BY_ID.get(pid);
  try {
    const m = $('Split Cohort Into Patients').itemMatching(i);
    if (m && m.json) return m.json;
  } catch (e) { /* pairing unavailable */ }
  return SRC[i] || {};
}

return $input.all().map((item, _i) => {
  const src = resolveSrc(item, _i);
  const err = item.json.error || item.json.message || 'Unknown transport error';

  return {
    json: {
      run_id: src.run_id,
      patient_id: src.patient_id,
      case_index: src.case_index,
      sample_index: src.sample_index,
      fl_checkpoint: src.fl_checkpoint,
      fl_round: src.fl_round,
      analysed_at: new Date().toISOString(),

      prediction: src.prediction,
      predicted_class_aami: src.predicted_class_aami,
      true_class_aami: src.true_class_aami,
      correct: src.correct,
      confidence: src.confidence,
      uncertainty_level: src.uncertainty_level,
      normalized_entropy: src.normalized_entropy,
      class_recall: src.class_recall,

      api_status: 'transport_error',
      api_error_detail: String(err).slice(0, 500),
      urgency_level: 'Unknown',
      suggested_next_action: 'Manual clinical assessment - automated agent unavailable',
      doctor_technical_alert: 'AGENT UNAVAILABLE. No machine analysis produced for this patient.',
      family_reassurance_message: 'The medical team is reviewing this record directly.',
      pipeline_recommendation: src.pipeline_recommendation || 'Not provided',

      clinical_status: 'Indeterminate',
      risk_score: 1.0,
      low_confidence_flag: true,
      disagreement_flag: false,
      blind_class_risk: false,
      ground_truth_miss: src.correct === false,
      human_review_required: true,
      review_reason: 'FAIL-SAFE: clinical agent unreachable - escalated by default',
      governance_policy: 'v2.0-integrated fail-safe path'
    }
  };
});

