// ---------------------------------------------------------------------------
// BUILD AUDIT RECORD
// Convergence point for all branches. One tamper-evident record per patient,
// chained to the federated checkpoint and round that produced the prediction.
// Checksum is pure-JS FNV-1a (n8n's Code sandbox blocks node builtins).
// ---------------------------------------------------------------------------

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return ('00000000' + h.toString(16)).slice(-8);
}

return $input.all().map(item => {
  const d = item.json;

  const record = {
    audit_version: '2.0-integrated',
    run_id:     d.run_id     || 'unknown',
    patient_id: d.patient_id || 'unknown',
    logged_at:  new Date().toISOString(),

    // provenance back into the federated pipeline
    fl_checkpoint: d.fl_checkpoint || 'unknown',
    fl_round:      d.fl_round ?? null,
    sample_index:  d.sample_index ?? null,

    // what the federated model said
    prediction:            d.prediction || 'unknown',
    predicted_class_aami:  d.predicted_class_aami || 'unknown',
    true_class_aami:       d.true_class_aami || 'unknown',
    confidence:            d.confidence ?? null,
    calibrated_confidence: d.calibrated_confidence ?? null,
    uncertainty_level:     d.uncertainty_level || 'unknown',
    normalized_entropy:    d.normalized_entropy ?? null,
    class_recall:          d.class_recall ?? null,

    // explainability evidence
    dominant_ecg_region: d.dominant_ecg_region || 'unknown',
    qrs_shap_signed:     d.qrs_shap_signed ?? null,

    // what the agent said
    api_status:            d.api_status || 'unknown',
    urgency_level:         d.urgency_level || 'unknown',
    suggested_next_action: d.suggested_next_action || 'unknown',

    // what the orchestrator decided, and why
    clinical_status:       d.clinical_status || 'unknown',
    risk_score:            d.risk_score ?? null,
    human_review_required: d.human_review_required ?? false,
    review_reason:         d.review_reason || 'not recorded',
    governance_policy:     d.governance_policy || 'not recorded',
    route:                 d.route || 'unknown',

    // what the human did
    clinical_review_status: d.clinical_review_status || 'Not required',
    review_mode:            d.review_mode || 'n/a',
    hitl_released_at:       d.hitl_released_at || null,

    // research flags for the results chapter
    low_confidence_flag: d.low_confidence_flag ?? false,
    disagreement_flag:   d.disagreement_flag ?? false,
    blind_class_risk:    d.blind_class_risk ?? false,
    ground_truth_miss:   d.ground_truth_miss ?? false
  };

  record.integrity_checksum = fnv1a(JSON.stringify(record));
  record.audit_status = 'Completed';

  return { json: record };
});

// ---------------------------------------------------------------------------
// AGGREGATE AUDIT LOG
// Build Audit Record emits ONE ITEM PER PATIENT, which is useful in the n8n UI
// but means the downstream file nodes run once per patient and each write
// overwrites the last - leaving only the final patient on disk.
// This node collapses the run into a single item so exactly one audit file is
// written, containing every patient plus run-level summary statistics.
// ---------------------------------------------------------------------------

const records = $input.all().map(i => i.json);

const escalated = records.filter(r => r.human_review_required);
const count = (pred) => records.filter(pred).length;

return [{
  json: {
    audit_log_version: "2.0-integrated",
    run_id: records[0]?.run_id || "unknown",
    generated_at: new Date().toISOString(),
    fl_checkpoint: records[0]?.fl_checkpoint || "unknown",
    fl_round: records[0]?.fl_round ?? null,

    summary: {
      patients_processed:   records.length,
      escalated_to_human:   escalated.length,
      auto_cleared:         records.length - escalated.length,
      escalation_rate:      records.length ? Number((escalated.length / records.length).toFixed(3)) : 0,
      high_uncertainty:     count(r => r.uncertainty_level === 'High'),
      low_confidence:       count(r => r.low_confidence_flag),
      disagreements:        count(r => r.disagreement_flag),
      blind_class_exposure: count(r => r.blind_class_risk),
      ground_truth_misses:  count(r => r.ground_truth_miss),
      transport_errors:     count(r => r.api_status === 'transport_error'),
      mean_risk_score:      records.length
        ? Number((records.reduce((a, r) => a + (r.risk_score || 0), 0) / records.length).toFixed(4))
        : 0
    },

    records: records
  }
}];
